 32	void HAL_Delay(uint32_t Delay)
 33	{
 34	    if (xTaskGetSchedulerState() != taskSCHEDULER_NOT_STARTED) {
 35	        vTaskDelay(pdMS_TO_TICKS(Delay));
 36	    } else {
 37	        /* Vòng lặp chờ thô khi scheduler chưa khởi chạy */
 38	        for (volatile uint32_t i = 0; i < Delay * 4000; i++) {
 39	            __asm__("nop");
 40	        }
 41	    }
 42	}
