 44	/* Khởi tạo ngoại vi phần cứng: 4 LED và nút WAKEUP PA0 */
 45	static void prvSetupHardware(void)
 46	{
 47	    /* Bật clock AHB1 cho GPIOA, GPIOD, GPIOG, GPIOK */
 48	    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIODEN | RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN;
 49	
 50	    /* Cấu hình PA0 (Nút WAKEUP): Chế độ Input (00), Pull-down (10) */
 51	    GPIOA->MODER &= ~(3UL << (BUTTON_PIN * 2));
 52	    GPIOA->PUPDR &= ~(3UL << (BUTTON_PIN * 2));
 53	    GPIOA->PUPDR |= (2UL << (BUTTON_PIN * 2));
 54	
 55	    /* Cấu hình PG6 (LED1): Chế độ Output (01), tắt ban đầu (LED tích cực mức thấp) */
 56	    GPIOG->MODER &= ~(3UL << (LED1_PIN * 2));
 57	    GPIOG->MODER |= (1UL << (LED1_PIN * 2));
 58	    GPIOG->BSRR = (1UL << LED1_PIN);
 59	
 60	    /* Cấu hình PD4 (LED2) & PD5 (LED3): Chế độ Output (01), tắt ban đầu */
 61	    GPIOD->MODER &= ~((3UL << (LED2_PIN * 2)) | (3UL << (LED3_PIN * 2)));
 62	    GPIOD->MODER |= ((1UL << (LED2_PIN * 2)) | (1UL << (LED3_PIN * 2)));
 63	    GPIOD->BSRR = (1UL << LED2_PIN) | (1UL << LED3_PIN);
 64	
 65	    /* Cấu hình PK3 (LED4): Chế độ Output (01), tắt ban đầu */
 66	    GPIOK->MODER &= ~(3UL << (LED4_PIN * 2));
 67	    GPIOK->MODER |= (1UL << (LED4_PIN * 2));
 68	    GPIOK->BSRR = (1UL << LED4_PIN);
 69	}
