 71	/* Task 1: Nháy LED1 (PG6) theo chu kỳ 1000 ms (500 ms bật, 500 ms tắt) */
 72	static void vTaskLED1(void *pvParameters)
 73	{
 74	    (void)pvParameters;
 75	    for (;;) {
 76	        GPIOG->BSRR = (1UL << (LED1_PIN + 16)); /* Bật LED1 (mức thấp) */
 77	        vTaskDelay(pdMS_TO_TICKS(500));
 78	        GPIOG->BSRR = (1UL << LED1_PIN);        /* Tắt LED1 (mức cao) */
 79	        vTaskDelay(pdMS_TO_TICKS(500));
 80	    }
 81	}
 82	
 83	/* Task 2: Nháy LED2 (PD4) theo chu kỳ 400 ms (200 ms bật, 200 ms tắt) */
 84	static void vTaskLED2(void *pvParameters)
 85	{
 86	    (void)pvParameters;
 87	    for (;;) {
 88	        GPIOD->BSRR = (1UL << (LED2_PIN + 16)); /* Bật LED2 */
 89	        vTaskDelay(pdMS_TO_TICKS(200));
 90	        GPIOD->BSRR = (1UL << LED2_PIN);        /* Tắt LED2 */
 91	        vTaskDelay(pdMS_TO_TICKS(200));
 92	    }
 93	}
