148	/* Task 5: Quản lý hiển thị LCD DSI OTM8009A và cập nhật giao diện */
149	static void vTaskLCD(void *pvParameters)
150	{
151	    (void)pvParameters;
152	    uint32_t rx_msg = 0;
153	
154	    /* Khởi tạo SDRAM và màn hình LCD DSI */
155	    UI_Init();
156	
157	    for (;;) {
158	        if (xQueueReceive(xUIQueue, &rx_msg, portMAX_DELAY) == pdPASS) {
159	            UI_ToggleScreen();
160	        }
161	    }
162	}
